import numpy as np, math

class Body:
 def __init__(self,x,w,h):
  self.p=np.array([x,h/2+.01],float); self.v=np.zeros(2); self.a=0.;self.av=0.;self.w=w;self.h=h;self.ii=12/(w*w+h*h)
 def vertices(self):
  c,s=np.cos(self.a),np.sin(self.a)
  return np.array([[-self.w/2,-self.h/2],[self.w/2,-self.h/2],[self.w/2,self.h/2],[-self.w/2,self.h/2]])@np.array([[c,s],[-s,c]])+self.p
 def axes(self):
  c,s=np.cos(self.a),np.sin(self.a);return np.array([[c,s],[-s,c]])

def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def vel(b,r):return b.v+b.av*np.array([-r[1],r[0]])
def impulse(b,j,r):
 b.v+=j;b.av+=cross(r,j)*b.ii

def clip(poly,point,n):
 result=[]
 for k,a in enumerate(poly):
  b=poly[(k+1)%len(poly)]; da=np.dot(a-point,n); db=np.dot(b-point,n)
  if da>=-1e-9:result.append(a)
  if (da<0) "'!= (db<0): result.append(a+(b-a)*da/(da-db))
 return np.array(result)

def collision(a,b):
 pa,pb=a.vertices(),b.vertices();sep=1e9;normal=None
 for n in np.r_[a.axes(),b.axes()]:
  aa=pa@n;bb=pb@n; d=min(aa.max(),bb.max())-max(aa.min(),bb.min())
  if d<=0:return []
  if d<sep:sep=d;normal=n if np.dot(b.p-a.p,n)>0 else -n
 # convex intersect
 poly=pa
 for k,point in enumerate(pb):
  edge=pb[(k+1)%4]-point;n=np.array([-edge[1],edge[0]])
  poly=clip(poly,point,n)
  if len(poly)==0:return []
 tangent=np.array([-normal[1],normal[0]])
 ss=poly@tangent
 pts=[poly[np.argmin(ss)],poly[np.argmax(ss)]]
 if np.linalg.norm(pts[0]-pts[1])<.2:pts=pts[:1]
 return [(a,b,p,normal,sep) for p in pts]

def simulate():
 bodies=[Body(x,w,55) for x,w in zip([59.5,83,106,129.5,151.5,171.5],[11,11,11,10,11,11])]
 dt=1/360;out=[]
 for step in range(1800):
  t=step*dt
  if step==216:impulse(bodies[-1],np.array([-38.,0]),np.array([0.,20.]))
  for b in bodies:
   b.v[1]-=650*dt; b.v*=.9997;b.av*=.9996
   b.p+=b.v*dt;b.a+=b.av*dt
  contacts=[]
  for b in bodies:
   for p in b.vertices():
    if p[1]<.05:contacts.append([None,b,p,np.array([0.,1.]),max(0,-p[1])])
  for i,a in enumerate(bodies):
   for b in bodies[i+1:]:
    if np.linalg.norm(b.p-a.p)<70:contacts.extend(collision(a,b))
  constraints=[]
  for a,b,p,n,d in contacts:
   ra=p-a.p if a else np.zeros(2);rb=p-b.p;tv=np.array([-n[1],n[0]])
   kn=1+cross(rb,n)**2*b.ii+(1+cross(ra,n)**2*a.ii if a else 0)
   kt=1+cross(rb,tv)**2*b.ii+(1+cross(ra,tv)**2*a.ii if a else 0)
   bias=min(25,max(0,d-.015)*.13/dt)
   constraints.append([a,b,ra,rb,n,tv,kn,kt,bias,0.,0.])
  for it in range(12):
   for z in constraints:
    a,b,ra,rb,n,tv,kn,kt,bias,jn,jt=z
    rv=vel(b,rb)-(vel(a,ra) if a else 0)
    new=max(0,jn+(bias-np.dot(rv,n))/kn);dn=new-jn;z[9]=new
    if a:impulse(a,-n*dn,ra)
    impulse(b,n*dn,rb)
    rv=vel(b,rb)-(vel(a,ra) if a else 0)
    limit=.7*new;newt=np.clip(jt-np.dot(rv,tv)/kt,-limit,limit);dif=newt-jt;z[10]=newt
    if a:impulse(a,-tv*dif,ra)
    impulse(b,tv*dif,rb)
  if step%90==0:out.append(np.array([[*b.p,b.a] for b in bodies]))
 return np.array(out)
if __name__=='"'__main__':
 out=simulate();np.save('.tmp/sim.npy',out)
 for i,frame in enumerate(out):print(round(i*.25,2),[(round(x,1),round(z,1),round(a*180/np.pi,1)) for x,z,a in frame])
PY
